    string findContestMatch(int n) {
        vector<string> matches(n);
        for (int i = 0; i < n; i++) {
            matches[i] = to_string(i + 1);
        }
        while (n > 1) {
            for (int i = 0; i < n / 2; i++) {
                matches[i] = "(" + matches[i] + "," + matches[n - 1 - i] + ")";
            }
            n /= 2;
        }
        return matches[0];
    }
};

class Solution {
    public String findContestMatch(int n) {
        String[] matches = new String[n];
        for (int i = 0; i < n; i++) {
            matches[i] = String.valueOf(i + 1);
        }
        while (n > 1) {
            for (int i = 0; i < n / 2; i++) {
                matches[i] = "(" + matches[i] + "," + matches[n - 1 - i] + ")";
            }
            n /= 2;
        }
        return matches[0];
    }
}

/**
 * @param {number} n
 * @return {string}
 */
var findContestMatch = function(n) {
    let matches = Array.from({ length: n }, (_, i) => String(i + 1));
    while (n > 1) {
        for (let i = 0; i < Math.floor(n / 2); i++) {
            matches[i] = `(${matches[i]},${matches[n - 1 - i]})`;
        }
        n = Math.floor(n / 2);
    }
    return matches[0];
};
